"""it — faith_b."""

T = {
"faith_071": ("Che cosa significa il nome di Allah «As-Salam»?", ["La Pace, esente da ogni difetto", "Il Creatore", "Il Sostentatore", "Il Potente"], "As-Salam è tra i nomi elencati alla fine della sura Al-Hashr: Egli è la Pace, esente da ogni imperfezione."),
"faith_072": ("Quali attributi pone il versetto 59:22 accanto al nome di Allah, subito dopo «non vi è divinità all'infuori di Lui»?", ["Conoscitore dell'invisibile e del visibile, il Compassionevole", "Il Re e il Guerriero", "Il Ricco e il Generoso", "Il Forte e il Rapido"], "«Egli è Allah, non vi è divinità all'infuori di Lui, il Conoscitore dell'invisibile e del visibile. Egli è il Compassionevole, il Misericordioso.»"),
"faith_073": ("Che cosa ordina il Corano di fare con i nomi più belli di Allah?", ["InvocarLo con essi", "Solo contarli", "Scriverli sulle porte", "Tacere su di essi"], "«Ad Allah appartengono i nomi più belli: invocateLo con quelli.»"),
"faith_074": ("Come presenta la sura Ta-Ha i nomi di Allah?", ["«Allah, non vi è divinità all'infuori di Lui. A Lui appartengono i nomi più belli»", "«I Suoi nomi sono nascosti»", "«I Suoi nomi sono innumerevoli»", "«I Suoi nomi sono nove»"], "«Allah, non vi è divinità all'infuori di Lui. A Lui appartengono i nomi più belli.»"),
"faith_075": ("Quale formula usa il Corano per escludere ogni somiglianza con Allah?", ["«Nulla è simile a Lui, ed Egli è l'Audiente, il Vedente»", "«È il più grande dei re»", "«È come la luce»", "«Nessuno Lo vede»"], "«Nulla è simile a Lui, ed Egli è l'Audiente, il Vedente.»"),
"faith_076": ("Che cosa dice il Versetto del Trono riguardo al sopore e al sonno?", ["Non Lo colgono né sopore né sonno", "Dorme di notte", "Riposa il settimo giorno", "Veglia un giorno sì e uno no"], "«Non Lo coglie né sonnolenza né sonno.»"),
"faith_077": ("Che cosa dice il Corano della conoscenza di Allah riguardo a una foglia che cade?", ["Non cade una foglia senza che Egli la conosca", "Ne viene a sapere dopo", "Gli angeli Lo informano", "Non viene annotata"], "«Presso di Lui sono le chiavi dell'invisibile… non cade una foglia senza che Egli lo sappia.»"),
"faith_078": ("Di che cosa è più vicino Allah all'uomo, secondo la sura Qaf?", ["Della sua vena giugulare", "Della sua ombra", "Della sua voce", "Della sua casa"], "«Invero abbiamo creato l'uomo e sappiamo cosa gli sussurra l'anima: siamo a lui più vicini della sua vena giugulare.»"),
"faith_079": ("Come descrive il Corano gli angeli preposti al Fuoco?", ["Non disobbediscono ad Allah e fanno ciò che è loro ordinato", "Alcuni di loro esitano", "Dormono", "Scelgono"], "«…angeli duri e severi, che non disobbediscono ad Allah in quel che ordina loro e fanno ciò che è loro ordinato.»"),
"faith_080": ("Come descrive il Corano gli angeli rispetto alla parola di Allah?", ["Non Lo precedono nel parlare e agiscono secondo il Suo ordine", "Contestano i Suoi ordini", "Decidono da sé", "Tacciono sempre"], "«Sono invece servi onorati: non Lo precedono nel parlare e agiscono secondo il Suo ordine.»"),
"faith_081": ("Quale angelo il Corano nomina come colui che ha fatto scendere la rivelazione sul cuore del Profeta ﷺ?", ["Jibril (Gabriele)", "Mika'il (Michele)", "Israfil", "Malik"], "«Di': chi è nemico di Jibril? È lui che, con il permesso di Allah, l'ha fatta scendere sul tuo cuore.»"),
"faith_082": ("Quale altro angelo è nominato accanto a Jibril nella sura Al-Baqarah?", ["Mikal (Michele)", "Israfil", "Ridwan", "Munkar"], "«Chi è nemico di Allah, dei Suoi angeli, dei Suoi messaggeri, di Jibril e di Mikal…»"),
"faith_083": ("Quali oggetti di fede elenca il versetto 4:136?", ["Allah, il Suo Messaggero, il Libro rivelato e i Libri precedenti", "Solo il Libro", "Solo i profeti", "Solo gli angeli"], "«O voi che credete, credete in Allah e nel Suo Messaggero, nel Libro che ha fatto scendere sul Suo Messaggero e nella Scrittura che ha fatto scendere in precedenza.»"),
"faith_084": ("Quale Libro il Corano menziona come dato a Dawud?", ["Lo Zabur (i Salmi)", "La Torah", "Il Vangelo", "I Fogli di Ibrahim"], "«…e a Dawud abbiamo dato lo Zabur.»"),
"faith_085": ("Quale sura prende il nome dai jinn, che ascoltarono il Corano e credettero?", ["Al-Jinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Di': mi è stato rivelato che un gruppo di jinn ascoltò e disse: “Abbiamo ascoltato una recitazione meravigliosa.”»"),
"faith_086": ("Per che cosa sono stati creati i jinn e gli uomini, secondo la sura Adh-Dhariyat?", ["Perché adorino Lui", "Per riempire la terra", "Per costruire", "Per litigare"], "«Non ho creato i jinn e gli uomini se non perché Mi adorassero.»"),
"faith_087": ("Che cosa dice il Corano di ogni anima e della morte?", ["Ogni anima gusterà la morte", "Alcune anime non muoiono", "La morte è un dubbio", "La morte è un sonno senza fine"], "«Ogni anima gusterà la morte, e riceverete la vostra piena ricompensa solo nel Giorno della Resurrezione.»"),
"faith_088": ("In quale stato usciranno gli uomini, secondo la sura Az-Zalzalah, perché siano mostrate loro le opere?", ["In gruppi separati", "Tutti insieme in un'unica fila", "Addormentati", "Silenziosi e invisibili"], "«In quel Giorno gli uomini usciranno in gruppi separati, perché siano mostrate loro le loro opere.»"),
"faith_089": ("Come descrive la sura Al-Kahf il registro delle opere nell'Ultimo Giorno?", ["Non tralascia nulla, né piccolo né grande, senza averlo annoverato", "Registra solo le grandi opere", "Viene cancellato", "È scritto dagli uomini"], "«Diranno: “Guai a noi! Cos'è questo libro che non tralascia nulla, né piccolo né grande, senza averlo annoverato?”»"),
"faith_090": ("Che cosa dice il Corano delle membra nel Giorno del Giudizio?", ["Le mani parleranno e i piedi testimonieranno", "Resteranno mute", "Saranno nascoste", "Saranno trasformate"], "«In quel Giorno sigilleremo le loro bocche: saranno le loro mani a parlarCi e i loro piedi a testimoniare su ciò che avranno guadagnato.»"),
"faith_091": ("Come descrive il Corano la preghiera riguardo al suo orario?", ["Una prescrizione a ore fisse", "Libera a qualsiasi ora", "Una volta a settimana", "Solo di notte"], "«In verità la preghiera è per i credenti una prescrizione a tempi determinati.»"),
"faith_092": ("Da che cosa distoglie la preghiera, secondo la sura Al-'Ankabut?", ["Dalla turpitudine e dal male", "Dalla fame", "Dalla malattia", "Dal viaggio"], "«E assolvi all'orazione: in verità l'orazione preserva dalla turpitudine e da ciò che è riprovevole.»"),
"faith_093": ("Quale preghiera il Corano distingue come «la preghiera mediana»?", ["È nominata senza essere identificata, nell'ordine di custodire le preghiere", "Solo la preghiera dell'alba", "Solo la preghiera della sera", "La preghiera del venerdì"], "«Siate assidui alle preghiere e alla preghiera mediana, e stateVi davanti ad Allah devotamente.»"),
"faith_094": ("Per quale motivo il Corano ordina la preghiera, nella sura Ta-Ha?", ["Per il ricordo di Allah", "Per il riposo", "Per il raduno", "Per contare le ore"], "«In verità Io sono Allah: non vi è divinità all'infuori di Me. AdoraMi dunque ed esegui l'orazione per ricordarMi.»"),
"faith_095": ("Quale qualità della preghiera apre l'elenco dei credenti che avranno successo, in Al-Mu'minun?", ["L'umiltà (khushu') nella preghiera", "La lunghezza", "La rapidità", "Il numero"], "«Invero prospereranno i credenti, quelli che sono umili nella loro preghiera.»"),
"faith_096": ("Quale preghiera descrive la sura Al-Isra come «testimoniata» (mashhudah)?", ["La recitazione dell'alba", "La preghiera della sera", "La preghiera del mezzogiorno", "La preghiera del venerdì"], "«Esegui l'orazione dal declino del sole fino alla caduta della notte, e la recitazione dell'alba: in verità la recitazione dell'alba è testimoniata.»"),
"faith_097": ("Quali due cose ordina il Corano di cercare come aiuto?", ["La pazienza e la preghiera", "La forza e la ricchezza", "Il viaggio e il riposo", "Il silenzio e la solitudine"], "«O voi che credete, cercate aiuto nella pazienza e nella preghiera: in verità Allah è con i pazienti.»"),
"faith_098": ("Quante rak'ah ha la preghiera obbligatoria del Dhuhr?", ["Quattro", "Due", "Tre", "Cinque"], "Dhuhr, 'Asr e 'Isha hanno ciascuna quattro rak'ah obbligatorie; le scuole concordano su questo."),
"faith_099": ("Qual è l'ultima delle cinque preghiere quotidiane obbligatorie?", ["Al-'Isha", "Al-Fajr", "Al-Maghrib", "Al-'Asr"], "L'ordine è: Fajr, Dhuhr, 'Asr, Maghrib, 'Isha."),
"faith_100": ("Come si chiama la posizione di prosternazione nella preghiera?", ["Il sujud", "Il ruku'", "Il qiyam", "Il tashahhud"], "Il qiyam è lo stare in piedi, il ruku' l'inchino, il sujud la prosternazione e il tashahhud la seduta della testimonianza."),
"faith_101": ("Che cosa prevede il Corano per il malato o il viaggiatore durante il Ramadan?", ["Un numero uguale di giorni da recuperare", "Nulla del tutto", "Un obbligo doppio", "Un digiuno perpetuo"], "«Chi di voi è malato o in viaggio, digiuni in seguito altrettanti giorni.»"),
"faith_102": ("Quale scopo assegna il Corano al digiuno prescritto?", ["Raggiungere il timore di Allah (taqwa)", "Dimagrire", "Risparmiare denaro", "Riposarsi"], "«Il digiuno vi è prescritto come fu prescritto a coloro che vi precedettero, affinché siate timorati.»"),
"faith_103": ("Che cosa risponde Allah, in mezzo ai versetti sul digiuno, a chi Lo interroga sulla Sua vicinanza?", ["«Io sono vicino: rispondo all'appello di chi Mi invoca»", "«Attendete la notte»", "«Chiedete agli angeli»", "«Cercate lontano»"], "«Quando i Miei servi ti chiedono di Me, in verità Io sono vicino: rispondo all'invocazione di chi Mi invoca.»"),
"faith_104": ("Quante categorie di beneficiari della zakat elenca il Corano?", ["Otto", "Tre", "Cinque", "Dodici"], "«Le elemosine sono per i poveri, i bisognosi, quelli incaricati di raccoglierle, quelli i cui cuori sono da conquistare, per il riscatto degli schiavi, per i debitori, per la causa di Allah e per il viandante.»"),
"faith_105": ("Quale effetto attribuisce il Corano alla zakat prelevata dai beni?", ["Purifica e fa crescere", "Impoverisce", "È simbolica", "Sostituisce la preghiera"], "«Preleva sui loro beni un'elemosina, con la quale li purifichi e li mondi.»"),
"faith_106": ("Quali due obblighi il Corano associa più spesso?", ["La preghiera e la zakat", "Il digiuno e il viaggio", "Il pellegrinaggio e il commercio", "La lettura e la scrittura"], "«Assolvete all'orazione e versate la zakat: tutto il bene che avrete anticipato per voi stessi, lo ritroverete presso Allah.»"),
"faith_107": ("Che cosa dice il Corano che giunge ad Allah nel sacrificio?", ["Né la carne né il sangue, ma il timore del credente", "Solo la carne", "Solo il sangue", "Il numero degli animali"], "«Le loro carni e il loro sangue non giungono ad Allah: giunge a Lui il vostro timore.»"),
"faith_108": ("Qual è la migliore provvista per il pellegrinaggio, secondo il Corano?", ["Il timore di Allah (taqwa)", "L'oro", "Il cibo", "Le cavalcature"], "«Fate provviste, ma la provvista migliore è il timore di Allah.»"),
"faith_109": ("Quale rito menziona il Corano attorno all'Antica Casa?", ["La circumambulazione (tawaf)", "La corsa nel deserto", "La salita di una collina", "Il digiuno sul posto"], "«…e girino attorno all'Antica Casa.»"),
"faith_110": ("Dove ordina il Corano di ricordare Allah, dopo aver lasciato 'Arafat?", ["Presso al-Mash'ar al-Haram, a Muzdalifah", "Sul monte Uhud", "A Quba", "A Ta'if"], "«Quando poi lasciate 'Arafat, ricordate Allah presso al-Mash'ar al-Haram.»"),
"faith_111": ("Quale tipo di pentimento chiede il Corano ai credenti?", ["Un pentimento sincero (tawbah nasuh)", "Un pentimento scritto", "Un pentimento pubblico", "Un pentimento annuale"], "«O voi che credete, tornate ad Allah con sincero pentimento.»"),
"faith_112": ("Che cosa dice la sura Ash-Shura dell'accettazione del pentimento?", ["È Lui che accoglie il pentimento dei Suoi servi e perdona i misfatti", "Il pentimento non è accolto", "Serve un intermediario", "Bisogna attendere un anno"], "«Ed è Lui che accoglie il pentimento dei Suoi servi e perdona i misfatti, e conosce quello che fate.»"),
"faith_113": ("Che cosa fanno coloro che il Corano loda, dopo aver commesso un male?", ["Ricordano Allah e chiedono perdono", "Fuggono", "Tacciono", "Accusano gli altri"], "«E coloro che, quando commettono una turpitudine o fanno torto a se stessi, ricordano Allah e chiedono perdono per i loro peccati.»"),
"faith_114": ("Con quale frequenza ordina il Corano il ricordo di Allah, nella sura Al-Ahzab?", ["Molto, al mattino e alla sera", "Una volta l'anno", "Una volta a settimana", "Solo in viaggio"], "«O voi che credete, ricordate Allah con frequente ricordo, e glorificateLo al mattino e alla sera.»"),
"faith_115": ("Su che cosa meditano «i dotati d'intelletto», alla fine della sura Al-'Imran?", ["Sulla creazione dei cieli e della terra, in ogni posizione", "Sui raccolti", "Sulle carovane", "Sulle genealogie"], "«Coloro che ricordano Allah in piedi, seduti e coricati sui loro fianchi, e meditano sulla creazione dei cieli e della terra.»"),
"faith_116": ("Che cosa ordina il Corano di fare una volta presa una decisione?", ["Riporre la propria fiducia in Allah", "Attendere un segno", "Interrogare un indovino", "Rinunciare"], "«E quando hai deciso, confida in Allah: in verità Allah ama coloro che confidano in Lui.»"),
"faith_117": ("Verso chi indirizza la sura Ash-Sharh il desiderio, una volta compiuto il compito?", ["Verso il suo Signore", "Verso il riposo", "Verso la famiglia", "Verso la gente"], "«Quando hai terminato, alzati, e rivolgi il tuo desiderio verso il tuo Signore.»"),
"faith_118": ("A che cosa paragona la sura Al-Hadid la vita di questo mondo?", ["A una pioggia la cui vegetazione piace, poi ingiallisce e diventa detrito", "A un lungo viaggio", "A una montagna", "A un oceano"], "«Sappiate che la vita di questo mondo non è che gioco… come una pioggia la cui vegetazione piace ai coltivatori; poi appassisce, la vedi ingiallire e infine diventa detrito.»"),
"faith_119": ("Che cosa dichiara il Corano migliore della ricchezza e dei figli, ornamento di questo mondo?", ["Le opere buone che perdurano", "L'oro", "La fama", "La terra"], "«La ricchezza e i figli sono l'ornamento della vita terrena, ma le opere buone che perdurano sono, presso il tuo Signore, migliori come ricompensa.»"),
"faith_120": ("Quale domanda pone il Corano sullo scopo della creazione dell'uomo?", ["«Pensavate che vi avessimo creati per gioco?»", "«Chi vi ha dato il nome?»", "«Dove andrete?»", "«Quanti siete?»"], "«Pensavate che vi avessimo creati per gioco e che non sareste stati ricondotti a Noi?»"),
"faith_121": ("Quale promessa fa il Corano a chi ricorda Allah?", ["«RicordateMi e vi ricorderò»", "«Sarai ricco»", "«Vivrai a lungo»", "«Viaggerai»"], "«RicordateMi dunque, e vi ricorderò. SiateMi riconoscenti e non rinnegateMi.»"),
"faith_122": ("A chi ordina il Corano di rimettere le controversie?", ["Ad Allah e al Messaggero ﷺ", "Agli anziani", "Al mercato", "Ai poeti"], "«E se siete in disaccordo su qualcosa, rimettetela ad Allah e al Messaggero, se credete in Allah e nell'Ultimo Giorno.»"),
"faith_123": ("Come descrive la sura Al-Anfal i cuori dei credenti alla menzione di Allah?", ["I loro cuori fremono, e la fede aumenta alla recitazione", "Si induriscono", "Si addormentano", "Dimenticano"], "«In verità i credenti sono coloro i cui cuori fremono quando si menziona Allah, e che vedono accrescersi la fede quando si recitano i Suoi versetti.»"),
"faith_124": ("Che cosa ordina il Corano di dedicare interamente al Signore dei mondi?", ["La preghiera, i riti, la vita e la morte", "Il commercio", "I raccolti", "I viaggi"], "«Di': in verità la mia preghiera, i miei riti, la mia vita e la mia morte appartengono ad Allah, Signore dei mondi.»"),
"faith_125": ("Quale condizione pone la sura Al-Bayyinah all'adorazione ordinata?", ["Adorare Allah con sincerità, dedicandoGli il culto puro", "Adorare in pubblico", "Adorare per iscritto", "Adorare solo in gruppo"], "«Non fu loro ordinato altro che adorare Allah, tributandoGli un culto puro, eseguire l'orazione e versare la zakat.»"),
"faith_126": ("Che cosa descrive il Corano come scorrente nei giardini promessi ai timorati?", ["Fiumi", "Strade", "Ponti", "Pozzi"], "Il Corano descrive ripetutamente i giardini «sotto i quali scorrono i fiumi»."),
"faith_127": ("Che cosa dice il Corano di ciò che è nascosto ai credenti come ricompensa?", ["Nessuna anima sa quale gioia degli occhi è loro riservata", "Tutto è descritto in dettaglio", "Sono ricchezze", "Sono regni"], "«Nessuna anima sa quale gioia degli occhi è loro riservata in ricompensa di quel che avranno fatto.»"),
"faith_128": ("Che cosa promette il Corano a chi fa il bene, oltre alla migliore ricompensa?", ["Un sovrappiù (ziyadah)", "Un rinvio", "Un regno", "Un libro"], "«Coloro che avranno fatto il bene avranno la migliore ricompensa e un sovrappiù.»"),
"faith_129": ("Come descrive il Corano l'accoglienza dei timorati alla porta del Paradiso?", ["«Pace su di voi, siete stati puri: entratevi per rimanervi in eterno»", "In silenzio", "Dopo una lunga prova", "Uno a uno senza una parola"], "«I suoi guardiani diranno: “Pace su di voi, siete stati buoni: entrate qui per rimanervi in eterno.”»"),
"faith_130": ("Verso che cosa ordina il Corano di affrettarsi, nella sura Al-'Imran?", ["Verso il perdono del Signore e un Paradiso ampio come i cieli e la terra", "Verso il mercato", "Verso il viaggio", "Verso la ricchezza"], "«Affrettatevi al perdono del vostro Signore e a un Giardino ampio come i cieli e la terra, preparato per i timorati.»"),
"faith_131": ("Quale responsabilità pone il Corano sul credente verso la sua famiglia?", ["Preservare loro, e se stesso, da un Fuoco", "Renderli ricchi", "Insegnare loro le lingue", "Portarli in viaggio"], "«O voi che credete, preservate voi stessi e le vostre famiglie da un Fuoco il cui combustibile sono gli uomini e le pietre.»"),
"faith_132": ("Come definisce il versetto 2:177 la vera pietà (al-birr)?", ["Credere in Allah, nell'Ultimo Giorno, negli angeli, nel Libro e nei profeti, e dare dei propri beni", "Volgere il viso a oriente o a occidente", "Solo digiunare", "Viaggiare"], "«La pietà non consiste nel volgere i volti a oriente o a occidente, ma pio è chi crede in Allah, nell'Ultimo Giorno, negli angeli, nel Libro e nei profeti.»"),
"faith_133": ("Chi vedrà le opere compiute, secondo la sura At-Tawbah?", ["Allah, il Suo Messaggero ﷺ e i credenti", "Nessuno", "Solo gli angeli", "I re"], "«E di': agite, Allah vedrà le vostre opere, e così il Suo Messaggero e i credenti.»"),
"faith_134": ("Con quale affermazione si chiude la sura Al-Ikhlas?", ["«E nessuno è eguale a Lui»", "«Egli è il più grande»", "«Egli è vicino»", "«Egli è il primo»"], "«E nessuno è eguale a Lui.»"),
"faith_135": ("Quali quattro nomi riunisce la sura Al-Hadid in un solo versetto?", ["Il Primo, l'Ultimo, il Manifesto e il Nascosto", "Il Re, il Santo, la Pace, il Fedele", "Il Creatore, l'Ideatore, il Plasmatore, il Saggio", "Il Vivente, l'Assoluto, l'Audiente, il Vedente"], "«Egli è il Primo e l'Ultimo, il Manifesto e il Nascosto, ed Egli è onnisciente riguardo a ogni cosa.»"),
"faith_136": ("Quali nomi elenca la fine della sura Al-Hashr dopo «il Sovrano»?", ["Il Santissimo, la Pace, il Fedele, il Custode", "Il Creatore, il Plasmatore", "Il Perdonatore, il Misericordioso", "L'Audiente, il Vedente"], "«Egli è Allah, il Sovrano, il Santissimo, la Pace, il Fedele, il Custode, l'Eccelso nella potenza.»"),
"faith_137": ("Come si chiama la formula «Non vi è divinità all'infuori di Allah, Muhammad è il Suo Messaggero»?", ["La shahadah (la testimonianza di fede)", "La basmalah", "La takbirah", "La tasmiyah"], "La shahadah è la prima parola dell'Islam e il primo dei suoi pilastri."),
"faith_138": ("Come si chiama la formula «Allahu akbar»?", ["Il takbir", "Il tahlil", "Il tasbih", "Il tahmid"], "Il takbir è «Allahu akbar», il tasbih è «subhan Allah», il tahmid è «al-hamdu lillah» e il tahlil è «la ilaha illa-llah»."),
"faith_139": ("Come si chiama la formula «Nel nome di Allah, il Compassionevole, il Misericordioso»?", ["La basmalah", "La hamdalah", "La hawqalah", "L'istirja'"], "La basmalah apre tutte le sure tranne una; la hawqalah è «la hawla wa la quwwata illa billah»."),
"faith_140": ("Quali parole insegna il Corano di dire quando colpisce una disgrazia?", ["«In verità apparteniamo ad Allah e a Lui faremo ritorno»", "«Perché proprio a me?»", "«Passerà»", "«È la sorte degli uomini»"], "«Coloro che, quando li colpisce una disgrazia, dicono: “In verità apparteniamo ad Allah e a Lui faremo ritorno.”»"),
"faith_141": ("Che cosa ordina il Corano di dire quando si annuncia un'azione per il domani?", ["«Se Allah vuole» (in sha' Allah)", "«È promesso»", "«Senza fallo»", "«Lo giuro»"], "«E non dire mai di nulla: “Domani farò questo”, senza aggiungere: “Se Allah vuole.”»"),
"faith_142": ("Quale conoscenza riserva il Corano ad Allah solo, alla fine della sura Luqman?", ["L'Ora, la pioggia, ciò che è negli uteri, ciò che si guadagnerà domani e dove si morirà", "Il numero delle stelle", "I nomi dei re", "Il conto dei giorni"], "«In verità Allah ha la scienza dell'Ora, fa scendere la pioggia e conosce ciò che è negli uteri. Nessuno sa cosa guadagnerà domani, e nessuno sa in quale terra morirà.»"),
"faith_143": ("Che cosa dice il Corano del termine fissato per ogni comunità?", ["Quando giunge, non è ritardato né anticipato di un'ora", "Può essere cambiato", "È ignoto ad Allah", "Dipende dai re"], "«Ogni comunità ha un termine: quando giunge il loro termine, non lo ritarderanno di un'ora né lo anticiperanno.»"),
"faith_144": ("Che cosa promette il Corano a chi compie il bene, uomo o donna, essendo credente?", ["Una vita buona, e una ricompensa secondo le migliori delle loro opere", "La ricchezza", "Il potere", "La fama"], "«Chi compie il bene, maschio o femmina, essendo credente, gli faremo vivere una vita buona.»"),
"faith_145": ("Quale distinzione traccia il Corano tra «islam» e «fede» nella sura Al-Hujurat?", ["Dire «ci siamo sottomessi» non è ancora la fede entrata nei cuori", "Sono la stessa parola", "La fede viene sempre prima", "L'islam è solo per i dotti"], "«I beduini dicono: “Abbiamo creduto.” Di': “Non avete creduto; dite piuttosto: ci siamo sottomessi, ché la fede non è ancora entrata nei vostri cuori.”»"),
"faith_146": ("Quale regola enuncia la sura Al-Ma'idah su una singola vita?", ["Chi uccide un uomo è come se avesse ucciso tutta l'umanità; chi ne salva uno, come se l'avesse salvata tutta", "Ogni vita conta per una", "Contano solo i parenti", "Contano solo i numeri"], "«Chi uccide un uomo, senza che questi abbia ucciso o seminato corruzione sulla terra, è come se avesse ucciso tutta l'umanità; e chi ne salva uno, è come se avesse salvato tutta l'umanità.»"),
"faith_147": ("Per quanto il Corano moltiplica la ricompensa di una buona azione?", ["Per dieci", "Per due", "Per cento", "Non viene moltiplicata"], "«Chi verrà con una buona azione, ne avrà dieci volte tanto; e chi verrà con una cattiva azione, non sarà compensato che con il suo equivalente.»"),
"faith_148": ("Come descrive la sura Fatir il rapporto degli uomini con Allah?", ["Sono i poveri bisognosi di Lui, mentre Allah è Colui che basta a Se stesso, il Degno di lode", "Sono Suoi soci", "Sono indipendenti", "Sono Suoi creditori"], "«O uomini, siete voi ad avere bisogno di Allah, mentre Allah basta a Se stesso ed è il Degno di lode.»"),
"faith_149": ("Quali quattro qualità salvano dalla perdita, secondo la sura Al-'Asr?", ["La fede, le opere buone, l'esortarsi al vero e l'esortarsi alla pazienza", "Ricchezza, forza, bellezza, astuzia", "Silenzio, sonno, ritiro, digiuno", "Viaggio, commercio, scrittura, lettura"], "«Per il tempo! In verità l'uomo è in perdita, eccetto coloro che credono, compiono il bene, si esortano al vero e si esortano alla pazienza.»"),
"faith_150": ("In che cosa dichiarano di credere i credenti, nel penultimo versetto della sura Al-Baqarah?", ["In Allah, nei Suoi angeli, nei Suoi libri e nei Suoi messaggeri", "In un solo libro", "In un solo angelo", "Nei loro antenati"], "«Il Messaggero crede in quello che è stato fatto scendere su di lui da parte del suo Signore, come i credenti: tutti credono in Allah, nei Suoi angeli, nei Suoi libri e nei Suoi messaggeri.»"),
}
